-- WP-34: the student edition (rulings R130–R135).
--
-- Generated by drizzle-kit and corrected by hand. drizzle runs every pending
-- migration inside one transaction, where `PRAGMA foreign_keys=OFF` is a no-op,
-- so the generated "drop and rename" rebuild of `students` would fail: dropping a
-- parent that team members, mentorships and competitions point at is an implicit
-- DELETE that breaks their foreign keys at once. Instead the constraint checks
-- are deferred to COMMIT, the rows are parked in a plain copy, and they are put
-- back into the *final* `students` table — every insert into a parent settles
-- the deferred violations of the children it satisfies, so the counter is back
-- at zero before the transaction commits. `roles` has no row-level dependants
-- that would break (user_roles.role_id is re-satisfied the same way).
PRAGMA defer_foreign_keys = ON;
--> statement-breakpoint
-- 1. roles: the CHECK gains STUDENT (R131), and the STUDENT row is seeded with a
--    literal UUIDv7 like the other two (migration 0003).
CREATE TABLE `__roles_copy` AS SELECT `id`, `key`, `name` FROM `roles`;
--> statement-breakpoint
DROP TABLE `roles`;
--> statement-breakpoint
CREATE TABLE `roles` (
	`id` text PRIMARY KEY NOT NULL,
	`key` text NOT NULL,
	`name` text NOT NULL,
	CONSTRAINT "roles_key_check" CHECK("key" in ('ADMINISTRATOR', 'PROFESSOR', 'STUDENT'))
);
--> statement-breakpoint
INSERT INTO `roles` (`id`, `key`, `name`) SELECT `id`, `key`, `name` FROM `__roles_copy`;
--> statement-breakpoint
DROP TABLE `__roles_copy`;
--> statement-breakpoint
CREATE UNIQUE INDEX `roles_key_uq` ON `roles` (`key`);
--> statement-breakpoint
INSERT INTO `roles` (`id`, `key`, `name`)
VALUES ('01926b00-0000-7000-8000-000000000003', 'STUDENT', 'Student')
ON CONFLICT (`key`) DO NOTHING;
--> statement-breakpoint
-- 2. students: the roll number is optional on a student install (R135); the
--    unique index covers only the rows that have one. Same columns, same order.
CREATE TABLE `__students_copy` AS SELECT * FROM `students`;
--> statement-breakpoint
DROP TABLE `students`;
--> statement-breakpoint
CREATE TABLE `students` (
	`id` text PRIMARY KEY NOT NULL,
	`organization_id` text NOT NULL,
	`university_id` text,
	`university_id_key` text,
	`full_name` text NOT NULL,
	`preferred_name` text,
	`institutional_email` text,
	`phone` text,
	`home_department_id` text NOT NULL,
	`program` text NOT NULL,
	`branch` text,
	`graduation_year` integer,
	`is_external` integer DEFAULT false NOT NULL,
	`external_institution` text,
	`status` text DEFAULT 'ACTIVE' NOT NULL,
	`notes` text,
	`privacy_notice_ack_at` integer,
	`erased_at` integer,
	`created_at` integer NOT NULL,
	`created_by` text,
	`updated_at` integer NOT NULL,
	`version` integer DEFAULT 1 NOT NULL,
	FOREIGN KEY (`organization_id`) REFERENCES `organizations`(`id`) ON UPDATE no action ON DELETE no action,
	FOREIGN KEY (`home_department_id`) REFERENCES `departments`(`id`) ON UPDATE no action ON DELETE no action,
	FOREIGN KEY (`created_by`) REFERENCES `users`(`id`) ON UPDATE no action ON DELETE no action,
	CONSTRAINT "students_program_check" CHECK("program" in ('BTECH', 'MTECH', 'BSC', 'MSC', 'BCA', 'MCA', 'PHD', 'OTHER')),
	CONSTRAINT "students_status_check" CHECK("status" in ('ACTIVE', 'INACTIVE', 'ALUMNI')),
	CONSTRAINT "students_graduation_year_check" CHECK("graduation_year" is null or "graduation_year" between 1950 and 2100),
	CONSTRAINT "students_notes_length_check" CHECK("notes" is null or length("notes") <= 500),
	CONSTRAINT "students_version_check" CHECK("version" >= 1)
);
--> statement-breakpoint
